def merge_sorted(a, b):
    result = []
    i = 0
    j = 0
    while i < len(a) and j < len(b):
        if a[i] < b[j]:
            pick = a[i]
            i += 1
        elif a[i] > b[j]:
            pick = b[j]
            j += 1
        else:
            pick = a[i]
            i += 1
            j += 1
        if not result or result[-1] != pick:
            result.append(pick)
    while i < len(a):
        if not result or result[-1] != a[i]:
            result.append(a[i])
        i += 1
    while j < len(b):
        if not result or result[-1] != b[j]:
            result.append(b[j])
        j += 1
    return result

print(merge_sorted([1, 3, 5, 7], [2, 3, 4, 8]))
print(merge_sorted([], [1, 2]))
print(merge_sorted([1, 1, 2], [1, 2, 2]))
